>.</div></form>
<?php if($week&&$makeupTeacher!==''&&$makeupClass!==''&&$makeupSubject!==''):[$allGrid,$allMax]=tkb_matrix($slots);$approvedWeek=tkb_week_substitutions($week,true);?>
<form method="post" class="tkb-card p-3 mb-3" id="makeupBulkForm"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="makeup_request"><input type="hidden" name="return_submode" value="makeup"><input type="hidden" name="week_id" value="<?=e($week['id'])?>"><input type="hidden" name="makeup_teacher" value="<?=e($makeupTeacher)?>"><input type="hidden" name="makeup_course" value="<?=e($makeupCourse)?>"><div class="d-flex justify-content-between gap-2 flex-wrap mb-2"><div><h5 class="mb-1"><i class="bi bi-calendar-plus"></i> Chọn tiết trống để dạy bù</h5><div class="makeup-picker-note"><?=e($makeupTeacher)?> · <?=e($makeupSubject)?> · lớp <?=e($makeupClass)?>. Ô xanh là thời gian có thể đăng ký. Có thể tích nhiều ô cùng lúc.</div></div><div class="d-flex gap-2 align-items-center"><span class="makeup-selected-count" id="makeupSelectedCount">Đã chọn 0 tiết</span><button class="btn btn-success align-self-start"><i class="bi bi-send-check"></i> <?=$canApprove?'Xác nhận các tiết đã chọn':'Đăng ký các tiết đã chọn'?></button></div></div><div class="tkb-matrix-wrap"><table class="tkb-matrix"><thead><tr><th class="session-col">Buổi</th><th class="period-col">Tiết</th><?php for($d=2;$d<=7;$d++):?><th>Thứ <?=$d?><div class="small fw-normal"><?=e(date('d/m',strtotime(tkb_week_slot_date($week,$d))))?></div></th><?php endfor;?></tr></thead><tbody><?php foreach(['Sáng','Chiều']as$session):$count=max(1,(int)($allMax[$session]??4));for($p=1;$p<=$count;$p++):?><tr><?php if($p===1):?><th class="session-name" rowspan="<?=$count?>"><?=$session==='Sáng'?'S':'C'?></th><?php endif;?><th class="period-no"><?=$p?></th><?php for($d=2;$d<=7;$d++):$date=tkb_week_slot_date($week,$d);$teacherItems=[];foreach($slots as$s)if((string)($s['teacher']??'')===$makeupTeacher&&(int)$s['day']===$d&&(string)$s['session']===$session&&(int)$s['period']===$p)$teacherItems[]=$s;foreach($approvedWeek as$r)if((string)($r['substitute_teacher']??'')===$makeupTeacher&&(string)($r['date']??'')===$date&&(string)($r['session']??'')===$session&&(int)($r['period']??0)===$p)$teacherItems[]=['subject'=>(tkb_is_makeup_row($r)?'Dạy bù':'Dạy thay'),'class'=>(string)($r['class']??'')];$teacherBusy=!empty($teacherItems);$classBusy=tkb_class_busy_at($week,$makeupClass,$d,$session,$p,$date);$pendingConflict=false;foreach(tkb_substitutions()as$r)if(tkb_substitution_status($r)!=='rejected'&&(string)($r['date']??'')===$date&&(string)($r['session']??'')===$session&&(int)($r['period']??0)===$p&&((tkb_key((string)($r['substitute_teacher']??''))===tkb_key($makeupTeacher))||(tkb_is_makeup_row($r)&&tkb_same_class((string)($r['class']??''),$makeupClass)))){$pendingConflict=true;break;}$free=!$teacherBusy&&!$classBusy&&!$pendingConflict;?><td class="<?=$free?'makeup-free':($classBusy?'makeup-class-busy':'makeup-busy')?>"><?php if($free):?><label><input type="checkbox" class="makeup-slot-check" name="makeup_slot[]" value="<?=e($d.'|'.$session.'|'.$p)?>"> Chọn</label><?php elseif($teacherBusy):?><?php foreach($teacherItems as$item):?><div><strong><?=e((string)($item['subject']??''))?></strong><br><?=e((string)($item['class']??$item['class_raw']??''))?></div><?php endforeach;?><?php elseif($classBusy):?><div>Lớp <?=e($makeupClass)?> đang học</div><?php else:?><div>Đã có đăng ký</div><?php endif;?></td><?php endfor;?></tr><?php endfor;endforeach;?></tbody></table></div><div class="row g-2 align-items-end"><div class="col-lg-9"><label class="form-label fw-bold mb-1">Ghi chú</label><input class="form-control form-control-sm" name="note" placeholder="Ví dụ: Dạy bù tiết nghỉ do hoạt động chung..."></div><div class="col-lg-3"><button class="btn btn-success w-100"><i class="bi bi-send-check"></i> <?=$canApprove?'Xác nhận các tiết đã chọn':'Gửi đăng ký các tiết đã chọn'?></button></div></div></form><script>(function(){const form=document.getElementById('makeupBulkForm'),count=document.getElementById('makeupSelectedCount');if(!form)return;const sync=()=>{const n=form.querySelectorAll('.makeup-slot-check:checked').length;if(count)count.textContent='Đã chọn '+n+' tiết';};form.addEventListener('change',e=>{if(e.target.classList.contains('makeup-slot-check'))sync();});form.addEventListener('submit',e=>{const n=form.querySelectorAll('.makeup-slot-check:checked').length;if(!n){e.preventDefault();alert('Hãy tích ít nhất một tiết trống để đăng ký dạy bù.');return;}if(!confirm('Xác nhận đăng ký '+n+' tiết dạy bù đã chọn?'))e.preventDefault();});sync();})();</script>
